Ltac fleaf c IH V R10 :=
  lazymatch goal with
  | H : msteps _ _ (@mkst ?fx2 ?R2 (Z_to_bv 64 0x3ae28) _ _) /\ _ |- _ =>
      let MS := fresh "MS" in let KS := fresh "KS" in
      split_exit H MS KS; raws;
      let A10 := fresh "A10" in
      first [ let A := get_reg R2 10%nat in pose proof A as A10 | assert (A10 := eq_trans (KS 10%nat ltac:(PMK.inl)) R10) ];
      lazymatch type of A10 with getr _ _ = Z_to_bv 64 ?dv =>
        apply (goal_pre _ _ _ _ fx2 R2 _ MS ltac:(intros k Hk; apply KS; revert k Hk; kin));
        apply (goal_same c dv);
        [ first [ reflexivity | replace (dv - p) with (c - p + (dv - c)) by lia; apply (ascii_pref l (c - p) (dv - c) LB); [lia| lia| lia| asc_byte ..] ]
        | apply (slow c IH fx2 R2 dv ltac:(lia) ltac:(lia) (vconst_keep _ R2 S e V ltac:(intros k Hk; apply KS; revert k Hk; kin)) A10) ] end
  | H : msteps _ _ (@mkst ?fx2 ?R2 (Z_to_bv 64 0x3aef0) _ _) /\ _ |- _ =>
      let MS := fresh "MS" in let KS := fresh "KS" in
      split_exit H MS KS; raws;
      let S6 := get_reg R2 23%nat in
      lazymatch type of S6 with getr _ _ = Z_to_bv 64 ?cv =>
        apply (goal_pre _ _ _ _ fx2 R2 _ MS ltac:(intros k Hk; apply KS; revert k Hk; kin));
        apply (goal_same c cv);
        [ replace (cv - p) with (c - p + 8) by lia; apply (ascii_pref l (c - p) 8 LB); [lia| lia| lia| asc_byte ..]
        | apply (join_case c IH fx2 R2 cv ltac:(lia) ltac:(lia) (vconst_keep _ R2 S e V ltac:(intros k Hk; apply KS; revert k Hk; kin)) S6) ] end
  end.
Ltac fleaves c IH V R10 := repeat (lazymatch goal with H : _ \/ _ |- _ => destruct H as [H|H]; [fleaf c IH V R10|] end); fleaf c IH V R10.

